public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 1000; // Example duration in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start;

        while (currentStart < end) {
            if (currentEnd + FETCH_DATA_DURATION > end) {
                timeRanges.add(new TimeRange(currentStart, end));
                break;
            }
            currentEnd += FETCH_DATA_DURATION;
            timeRanges.add(new TimeRange(currentStart, currentEnd));
        }

        return timeRanges;
    }

    private static class TimeRange {
        private long start;
        private long end;

        public TimeRange(long start, long end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public String toString() {
            return "TimeRange{" +
                    "start=" + start +
                    ", end=" + end +
                    '}';
        }
    }
}

