public static long compressTimeBucket(long timeBucket, int dayStep) {
    long startYear = timeBucket / 10000;
    long startMonth = (timeBucket / 100) % 100;
    long startDay = timeBucket % 100;
    long endYear = startYear + (dayStep - 1) / 365;
    long endMonth = startMonth + (dayStep - 1) % 30;
    long endDay = startDay + (dayStep - 1) % 30;
    return (endYear * 10000) + (endMonth * 100) + endDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = str.charAt(i);
        if ((b & 0x80) == 0) {
            size++;
        } else if ((b & 0xE0) == 0xC0) {
            size += 2;
        } else if ((b & 0xF0) == 0xE0) {
            size += 3;
        } else if ((b & 0xF8) == 0xF0) {
            size += 4;
        }
    }
    return size;
}

