public class SuffixSumCalculator {
    private static final long MOD = 1000000007;

    public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSum = bounds.stream()
                .map(i -> bounds.stream().skip(i).reduce(0, Integer::sum))
                .collect(Collectors.toList());
        long sum = bounds.stream().mapToInt(Integer::intValue).sum();
        return new Pair<>(suffixSum, sum);
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
