public class DoublyLinkedList<E> {
    private Node<E> head;
    private Node<E> tail;

    private static class Node<E> {
        E data;
        Node<E> prev;
        Node<E> next;

        Node(E data) {
            this.data = data;
            this.prev = null;
            this.next = null;
        }
    }

    public void addListNode(ListNodeImpl<E> node) {
        if (head == null) {
            head = tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
    }

    public void removeListNode(ListNodeImpl<E> node) {
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
    }

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        while (!list.isEmpty()) {
            ListNodeImpl<E> node = list.removeFirst();
            addListNode(node);
        }
    }
}

