public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }

    int end = nameStart;
    while (end < buf.length() && Character.isLetterOrDigit(buf.charAt(end))) {
        end++;
    }

    if (end - nameStart > 3) {
        buf.append(nameStart).append(end - nameStart).append(" ");
    } else {
        buf.append(nameStart).append(end - nameStart);
    }
}

